async function main() {
  console.log(`Starting insertion of ${newFoods.length} new clinical foods...`);
  
  let inserted = 0;
  let skipped = 0;

  for (const food of newFoods) {
    const existing = await prisma.food.findFirst({
      where: { name: food.name },
    });

    if (!existing) {
      await prisma.food.create({
        data: {
          name: food.name,
          category: food.category,
          calories: food.calories,
          proteinG: food.proteinG,
          carbsG: food.carbsG,
          fatG: food.fatG,
          fiberG: food.fiberG,
          source: 'clinical-spanish-catalog',
        },
      });
      inserted++;
    } else {
      skipped++;
    }
  }

  const total = await prisma.food.count();
  console.log(`Finished! Inserted: ${inserted}, Skipped: ${skipped}. Total foods now in database: ${total}`);
}

main()
  .catch(console.error)
  .finally(() => prisma.$disconnect());
